const BOSSES=[
  {name:"Matthias",chapter:2,region:"Hernand",quest:"Story - For Honor (Unterkapitel Hernand in Chaos)",drop_weapon:"–",drop_abyss_gear:"–",weakness:"–",parry_or_dodge:"Parry (Flurry-Ende)",strategy:"Watch & Learn: Pump Kick. Standard-Opener."},
  {name:"Kailok the Hornsplitter",chapter:2,region:"Hernand",quest:"End of Greed",drop_weapon:"Sword of the Lord",drop_abyss_gear:"Wind Slash",weakness:"–",parry_or_dodge:"Parry",strategy:"Shield + Force Palm. Slow but powerful hits."},
  {name:"Reed Devil",chapter:3,region:"Hernand - Mountain of Frozen Souls (Süd)",quest:"The Face Behind the Mask",drop_weapon:"–",drop_abyss_gear:"–",weakness:"–",parry_or_dodge:"Phase 1 Parry; Phase 2 Dodge Waves",strategy:"P1: Parry Flurry-Ende. P2: 5 Totems zerstören, Klone ignorieren, rote Waves dodgen. P3: Nahkampf, side-dodge."},
  {name:"Saigord the Staglord",chapter:null,region:"Hernand - Icemoor Castle Ruins",quest:"Faction - Lord Amidst the Ruins (King of the Fallen Kingdom)",drop_weapon:"Staglord's Shield",drop_abyss_gear:"–",weakness:"–",parry_or_dodge:"Dodge/Counter nach Heavy Attacks",strategy:"Watch & Learn: Turning Slash Expertise erlernen und gegen ihn einsetzen. Force Palm zum Cancel/Stagger. Phasen nach HP-Farbe: Blau defensiv, Grün offensiv (blockt viel), Rot mehr Heavy Attacks - nach deren Recovery kontern. Eis-Resistenz-Set nur defensiv (Kälte senkt Ausdauer-Regen), keine ausnutzbare Eis-Schwäche."},
  {name:"Marni's Excavatron",chapter:null,region:"Hernand - Karin Quarry",quest:"Faction: Stolen Quarry",drop_weapon:"Mining Knuckledrill",drop_abyss_gear:"Mining Mastery",weakness:"–",parry_or_dodge:"NIE Parry — Dodge alles",strategy:"Sword & Shield. Force Palm Lv3 (3-Chain). Drill glow → Force Palm cancelt Burrow. Final 5%: kein Groggy → nur Sustain."},
  {name:"Draven the Crowcaller",chapter:5,region:"The Abyss - Crow's Nest",quest:"Toward the Nest",drop_weapon:"Tauria Curved Sword",drop_abyss_gear:"Crow's Pursuit, Gale I, Wind Slash",weakness:"–",parry_or_dodge:"Mix",strategy:"3 HP-Bars. Aerial-Phasen: Glider nutzen. Reward auch: Blackwing Leather Mask + Armor."},
  {name:"Myurdin (Phase 1)",recur:"Phase 1 von 2 desselben Kampfes — verwandelt sich in Lava Myurdin",chapter:7,region:"Pailune - Ashclaw Keep",quest:"Battle at Silver Wolf Mountain",drop_weapon:"Melted Ambition",drop_abyss_gear:"Groundsurge",weakness:"–",parry_or_dodge:"Parry Slow-Sword; Dodge All-Fours-Bait",strategy:"All-Fours Stance = BAIT, nicht angreifen! Loop: Focus → Blinding Flash → Finisher → R2."},
  {name:"Lava Myurdin (Phase 2)",recur:"Phase 2 von 2 (Lava-Verwandlung des Myurdin-Kampfes)",chapter:7,region:"Pailune - Ashclaw Keep",quest:"Battle at Silver Wolf Mountain",drop_weapon:"(Drop nach Phase 1)",drop_abyss_gear:"Groundsurge",weakness:"–",parry_or_dodge:"Parry Slow-Sword; Dodge Lava Springs",strategy:"Lava-Bear-Charge 3-4x. Lava Springs: 1s Warnung → wegrollen. Jump-Slam: Bildschirm dunkel → Force Palm. MITTE halten!"},
  {name:"Hexe Marie",chapter:9,region:"Demeniss - Hexe Sanctuary",quest:"Black Witch",drop_weapon:"Crow Whisperer",drop_abyss_gear:"–",weakness:"Feuer (Barrier-Phase)",parry_or_dodge:"Parry Melee; Dodge Crow Barrage",strategy:"Vor-Quest: 4 Totems S→N. Crow Barrage: senkrecht zu ihr rollen. Adds: Urn Swordsman first. [Hidden Lore: Hexe Marie ist der korrumpierte/fragmentierte Teil des White Crow — daher die Mutter-Obsession gegenüber Kliff. Siehe Secrets-Section.]"},
  {name:"Golden Star",chapter:11,region:"Delesyia - Marni's Masterium",quest:"Master of a Forgotten Land",drop_weapon:"Power Core (Story)",drop_abyss_gear:"–",weakness:"Blitz P2 (3x Schaden)",parry_or_dodge:"Dodge alles",strategy:"P1: Marni-Spear-Pylons → L2+R2 → Stagger-Bar. Golem Adds sofort killen. P2: auf Blackstar, Force Palm aufs Auge."},
  {name:"Black Fang",chapter:null,region:"Hernand - Forest of Wolves (N The Sage's Peak)",quest:"Legendary Wolf",drop_weapon:"–",drop_abyss_gear:"Shadow Claw (+ Key Item: Leebur's Soul, deckt alle Legendary-Animal-Standorte auf)",weakness:"–",parry_or_dodge:"Dodge Lunges/Shadow Claw (wegrollen, dann auf ihn zurollen)",strategy:"Wolf-Adds mit Meteor Kick wegräumen, dann Nature's Grasp auf die Arena-Bäume auslösen (1 Baum-Treffer = >50% HP; Bäume per Force Palm fällen oder Lunges hineinlocken). Black Fang teleportiert + slasht — Lunges/Shadow-Claw dodgen. Reward: Leebur's Soul; das Silver-Fang-Mount kommt SEPARAT (eigenes Tier Silver Fang am Howling Hollow erlegen + häuten = Fang of Silver Fang → bei Witch zum Sigil craften). Die Blitz-Schwäche gehört zum getrennten Silver-Fang-Tier, nicht zu Black Fang."},
  {name:"Beloth the Darksworn",chapter:null,region:"Hernand - Hoenmark Ruins (Nord)",quest:"Faction - White Blizzard (House Lanford; Cursed Mountain / Wraith in the Frost)",drop_weapon:"Plate Helm of the Shadows (Rüstungsteil, keine Waffe)",drop_abyss_gear:"–",weakness:"Feuer",parry_or_dodge:"Dodge fast alles",strategy:"~3-Hit-Killer (Eis-Thema). Defensiv: FROSTCURSED ICE-RESISTENZ-SET stark empfohlen. Offensiv: Beloth ist anfällig für FEUER — Feuerwaffen ziehen ihm zusätzlich Schaden über Zeit ab (game8, Deltia's Gaming, PC Gamer, GameRant übereinstimmend). Geduld, kein Tank-and-Spank. Hinweis: Er droppt nur den HELM des Shadows-Sets — die übrigen Teile liegen verstreut in Truhen und Höhlen, siehe Rüstungs-Sektion."},
  {name:"Corrupted Caliburn",recur:"Korrumpierte Form von Gabriel Caliburn · Finale-Gauntlet 1/3 (Kap. 12)",chapter:12,region:"The Abyss",quest:"A Shadow in the Void",drop_weapon:"Twisted Verdict",drop_abyss_gear:"Abyssal Rays",weakness:"–",parry_or_dodge:"Parry Sword-Strings; Dodge Teleport-Smash",strategy:"SAVE VOR DEM GATE! Stillstand → hinter dodgen, 4 Heavy + Light bis Shadow-Wave → durchdodgen. [Hidden Lore: Caliburn ist eine Inkarnation von Umbra — siehe Run-108-Auflösung in Secrets-Section.]"},
  {name:"Avatar of Umbra",recur:"Finale-Gauntlet 2/3 — der besessene Myurdin (Bodenkampf, Quest 'Blinding Darkness')",chapter:12,region:"The Abyss",quest:"Blinding Darkness",drop_weapon:"–",drop_abyss_gear:"–",weakness:"–",parry_or_dodge:"Dodge rote Attacks",strategy:"Kombiniert alle Boss-Moves. Fire-Fist DoT + Ancestral Warriors. Maximum aggro + Healing."},
  {name:"Umbra (Final)",recur:"Finale-Gauntlet 3/3 — wahre Form (Drachenkampf, Quest 'Blinding Darkness')",chapter:12,region:"The Abyss",quest:"Blinding Darkness",drop_weapon:"Falling Palm Skill + 99.999 ATK Waffe",drop_abyss_gear:"–",weakness:"–",parry_or_dodge:"Dodge Lasers/Rocks",strategy:"Auf Blackstar. R1 Fireballs aufs Auge → Stagger → Dismount → Glide → Air-Dash → Force Palm aufs Auge (2-3x)."},
  {name:"Kearush the Slayer",chapter:5,region:"Hernand Highlands",quest:"Story",drop_weapon:"Abyss Artefakte",drop_abyss_gear:"–",weakness:"–",parry_or_dodge:"KEIN Parry/Block — Dodge alles",strategy:"Gorilla. Forward-right dodge → 3 schnelle Hits → disengage. Min: HP Lv4, Sta Lv4, Refine 4 Plate."},
  {name:"White Horn",recur:"Natürliche Version (Pailune-Yeti, mehrphasig) — auch als Clockwork White Horn",chapter:null,region:"Pailune",quest:"Side",drop_weapon:"–",drop_abyss_gear:"–",weakness:"Feuer (Pflicht!)",parry_or_dodge:"Dodge Ice-Breath (horizontal)",strategy:"Brazier in Arena entzünden. Fire-Element zwingend. Phase 2 Ice-Breath horizontal dodgen."},
  {name:"Priscus the Ancient",chapter:null,region:"Pailune - Spire of Ringing Truth",quest:"Faction",drop_weapon:"–",drop_abyss_gear:"Ancient Retribution",weakness:"–",parry_or_dodge:"Nature's Snare für Projektile",strategy:"Bow + Nature's Snare → Projektile zurückwerfen. Reward: Path of Trials (Frost Mantle Skill). Misc/Key-Item-Drop: Blessing of the Immortal (Consumable, ~10s Schadensimmunität — keine Waffe)."},
  {name:"Karanda",recur:"Legendäre Harpyien-Königin — Luftkampf über dem Nest",chapter:null,region:"Pailune - Harpy Nest (Berggipfel im Zentrum Pailunes)",quest:"Faction — Pailune-Miliz 'Nest of White Feathers' → 'Queen of the Skies' (schaltet nach 'Crossroads of Succession' frei)",drop_weapon:"–",drop_abyss_gear:"Pillar of Wind + Infinite Arrows II",weakness:"–",parry_or_dodge:"Dodge alles (KEIN Parry) — Nature's Snare gegen Projektile",strategy:"Fliegender Boss: kreist meist außerhalb der Nahkampfreichweite über der Gipfelplattform. Nature's Snare (L3+R3, rechter Stick im Uhrzeigersinn) absorbiert die Projektile, R3 schickt sie zurück; alternativ Focused Shot (Marksmanship Lv.2) auf das fliegende Ziel. Ihre Schneeklingen zweimal dodgen — beim Werfen UND beim Zurückziehen. Stagger aufbauen, bis sie landet, dann Turning Slash. Die kleineren Harpyien ignorieren. Mitbringen: Palmar Pills + Heilnahrung. Drop 'Eye of the Sky' schaltet das komplette Pailune-Regionswissen frei."},
  {name:"Antumbra's Sword",chapter:null,region:"Sanctum of Absolution",quest:"Sanctum",drop_weapon:"Vessel of Dark Pursuit",drop_abyss_gear:"Wound of Darkness",weakness:"–",parry_or_dodge:"Dodge Illusionen",strategy:"Enger Raum, Illusionen → Blinding Flash Spam."},
  {name:"One-Armed Ludvig",recur:"Spätere, SEPARATE 2. Ludvig-Begegnung (spätes Kap. 7, als Oongka)",chapter:7,region:"Demeniss - Kingshield Mountains",quest:"Story - Time to Face Justice (Twisted Fate, als Oongka)",drop_weapon:"–",drop_abyss_gear:"–",weakness:"–",parry_or_dodge:"Parry & Dodge",strategy:"Tritt direkt nach dem Lava-Myurdin-Fight auf. Humanoider Nahkampf-Boss — Combos mit einem Arm. Vorsicht nach dem langen Myurdin-Gauntlet: Ressourcen einteilen! (Regions-Hinweis, Stand 22.08.2026 — wahrscheinlich, Quellenkonflikt dokumentiert: Die Kingshield Mountains sind ein Grenzmassiv zwischen Demeniss, Hernand und Pailune. Quellen, die den KAMPFORT beschreiben, nennen Demeniss — Fextralifes Bossseite ('You will find Ludvig on the mountains in Demeniss during the quest Time to Face Justice') und GameRant vom 21.03.2026 ('a small graveyard in the Kingshield Mountains of Demeniss'). Quellen, die stattdessen die QUEST einsortieren, widersprechen sich: VULKK und game8 führen 'Time to Face Justice' unter Pailune, PowerPyx nennt Hernand als Startregion. Ausschlaggebend: game8 verortet die Kingshield Mountains auf der eigenen Rätsel- und Regionsseite selbst in Demeniss — die Pailune-Angabe steht gegen die eigene Geografie. Die Kapitel-Schlusssequenz spielt an einem SEPARATEN Friedhof in Pailune (PowerPyx: 'Return to Pailune and approach your allies at the graveyard') — das ist die wahrscheinlichste Ursache der Pailune-Zuordnung. Keine offizielle Pearl-Abyss-Quelle; mit VULKK steht eine Leitquelle auf der Gegenseite.)"},
  {name:"Lucian Bastier",recur:"Phase 1 von 2 desselben Kampfes (als Damiane)",chapter:8,region:"Demeniss - Spire of Clockwork",quest:"Story - A Fleeting Dream (Damiane-Solo)",drop_weapon:"–",drop_abyss_gear:"Flames of Judgment",weakness:"–",parry_or_dodge:"Dodge",strategy:"Damiane kämpft diesen Boss allein (Kliff nicht steuerbar). Nutze Damianes eigene Skills. Story-kritischer Fight in Demeniss (Quest 'A Fleeting Dream')."},
  {name:"Gregor the Halberd of Carnage",chapter:8,region:"Hernand - Fort Ironclad",quest:"Where The Wind Guides You",drop_weapon:"Golden Vanguard",drop_abyss_gear:"Abyss Artifact",weakness:"–",parry_or_dodge:"Dodge (Impaling Spear unblockbar)",strategy:"Vor Kampf: Pfeilfallen in der Halle zerstören. Langsame Drehrate ausnutzen — Backstab-Konter. Force Palm maxen → 3er-Combo → Stagger. Defensive Spielweise, Distanz halten."},
  {name:"Walter Lanford",chapter:null,region:"Hernand - Fort Warspike",quest:"Name Written in Blood",drop_weapon:"Dane Shotgun",drop_abyss_gear:"–",weakness:"–",parry_or_dodge:"Dodge (kein Block)",strategy:"Hochmobiler Pistolenschütze. Run-and-Hit-Ansatz. 'Poof'-Escape: zum Landepunkt dashen → Heavy Attack. Double Barrel Barrage: volle Distanz, sofort dodgen. Drops: Dane Shotgun + Rhonda Leather Boots + Golden Piggy Bank."},
  {name:"Master Du",chapter:9,region:"Crimson Desert - Cloister of Enlightenment",quest:"The Sage of the Desert",drop_weapon:"Master Du's Circlet",drop_abyss_gear:"Karmic Pulse",weakness:"–",parry_or_dodge:"Dodge (Green Ray: bis 3x konsekutiv)",strategy:"2 HP-Bars. Phase 1: defensiv, Konter bei Dash-Angriff. Phase 2: offensiv, Stagger mit Force Palm. Leg Sweep / Lariat / Scissor Takedown für Knockdown. Green Ray = sofort wegrollen. Schaltet Blinding Flash Finisher frei (2x erfolgreich ausweichen)."},
  {name:"Fortain the Cursed Knight",chapter:8,region:"Demeniss - Thornbriar Fortress",quest:"The Cursed Knight",drop_weapon:"Shackle of Might",drop_abyss_gear:"Abyss Artifact",weakness:"–",parry_or_dodge:"Dodge (Specter-Angriffe)",strategy:"Schwere Rüstung reduziert eigenen Schaden stark. Defensiv spielen. Seelen-Doppelgänger-Angriffe konsequent ausweichen. Recovery Items und Gear-Verbesserung am Amboss/Schleifstein vor dem Kampf. Lore: Verriet Lord Wells, wurde von der Schwarzen Hexe korrumpiert."},
  {name:"Awakened Ludvig",recur:"Phase 2 der 1. Ludvig-Begegnung (Pailune Castle, Quest 'Lonely Jackals')",chapter:7,region:"Pailune - Pailune Castle",quest:"Lonely Jackals (Phase 2)",drop_weapon:"Hungering Fang Leather Cloak",drop_abyss_gear:"–",weakness:"–",parry_or_dodge:"Dodge alles (unblockbar, kein Knockdown)",strategy:"Phase 2 nach dem normalen Ludvig-Kampf. Kann nicht gestaggert/knockt werden, bewegt sich extrem schnell, alle Hits unblockbar. Nur Dodge-Rolls + Recovery Items. Niederlage = gesamter Ludvig-Fight neu. Post-Fight: Ludvig flüchtet einarmig (One Armed Ludvig). Drops: Hungering Fang Leather Cloak + Boots."},
  {name:"Awakened Lucian Bastier",recur:"Phase 2 von 2 — verwandelter Lucian Bastier (derselbe Kampf)",chapter:8,region:"Demeniss - Spire of Clockwork",quest:"A Fleeting Dream (Phase 2)",drop_weapon:"Official Knight's Plate Armor",drop_abyss_gear:"–",weakness:"–",parry_or_dodge:"Dodge (Fiend Dash unblockbar)",strategy:"Phase 2 nach Lucian Bastier. Wechselt Shield+Morgenstern gegen riesige Armklinge. Fiend Dash = unblockbar, sofort kontern. Whirling Slash und Impale ausweichen. Force Palm 3-Combo fülltStagger-Bar schnell. Feuer-DoT-Schaden über Zeit beachten. Drops: Ponytail Ticket + Official Knight Set + Eclipsed Solas Plate Gloves + Spire Key."},
  {name:"Marni's Clockwork Mantis",chapter:10,region:"Delesyia - Regent's Rise",quest:"Frozen Hearted Predator",drop_weapon:"–",drop_abyss_gear:"–",weakness:"–",parry_or_dodge:"Dodge (Mantis Ray unblockbar)",strategy:"Mechanische fliegende Mantis. Begleitet von 3 Dragonfly Fighters — erst eliminieren! Block/Parry-Konter für normale Angriffe. Force Palm für Stagger-Bar. Mantis Ray (Feuer) = ausweichen, kein Block. Folgt nach Turbine-Kampf im Krall Foundry."},
  {name:"Turbine",chapter:10,region:"Delesyia - Krall Foundry",quest:"Invaders from the East",drop_weapon:"–",drop_abyss_gear:"–",weakness:"–",parry_or_dodge:"Mechanik-Boss (kein klassischer Kampf)",strategy:"180-Sekunden-Verteidigung: Generator schützen mit Valgash + Ironflame Orcs. Ironflame A.T.A.G. Mk.I Mech bedienen. Clockwork Wasps → Discharge EMP. Dragonfly Fighters → Rapidfire Gun. Mech Balloon Troopers → abschliessen während Flug. Danach: vollgeladene Kanone auf Turbines feuern. Führt direkt zu Marni's Clockwork Mantis."},
  {name:"Tenebrum",chapter:4,region:"Hernand - Scholastone Institute (Abyss-Riss / Spire of the Stars)",quest:"Story - Gate to the Otherworld",drop_weapon:"–",drop_abyss_gear:"Abyss Artifact (+ Key to the Spire of the Stars vom Dekan)",weakness:"–",parry_or_dodge:"Dodge (Luftkampf, bodenlose Arena)",strategy:"Erscheint, als Octavius in den Abyss gezogen wird. Bodenlose Arena gegen einen pausenlos kreisenden fliegenden Gegner: Blinding Flash aktivieren, um die Schwachpunkte sichtbar zu machen, dann per Doppelsprung + Force Palm in der Luft attackieren; hinter Säulen Spirit regenerieren."},
  {name:"Cassius Morten",chapter:6,region:"Hernand",quest:"Story - Cracks in the Shield (Traitor)",drop_weapon:"Shield of Betrayal",drop_abyss_gear:"–",weakness:"–",parry_or_dodge:"Parry Sword-Strings; Dodge Shadow-Surge",strategy:"Story-Boss Kap. 6 ('Traitor'). Schildträger mit einer Lebensleiste und langen Angriffsketten. Schwere Angriffe (R2) schaden auch durch den Block - nach 3 Treffern unterbrochen und für leichte Angriffe offen; Tauria Curved Sword + Nature's Echo empfohlen. Hinweis: Tenebrum ist ein eigener Kap.-4-Boss (Gate to the Otherworld), nicht Cassius' Verwandlung."},
  {name:"Gabriel Caliburn",recur:"1. Begegnung (Kap. 8, Skript-Niederlage) — kehrt als Corrupted Caliburn zurück",chapter:8,region:"Demeniss - Demeniss Castle",quest:"Story - The Blood Coronation (scripted Loss)",drop_weapon:"–",drop_abyss_gear:"–",weakness:"–",parry_or_dodge:"Scripted — kein klassischer Sieg",strategy:"SCRIPTED LOSS Kap. 8: Kliff verliert garantiert, egal wie gut man spielt. Cutscene-Übergang. Reale Rematch erst in Kap. 12 als Corrupted Caliburn. In 1.07 als Rematch-Boss bei Fort Musket via Laterne verfügbar."},
  // --- Auto-recherchiert 2026-06-03 (Fextralife/PowerPyx/game8); Roster 31->42, alle Bilder HTTP-verifiziert. Strategien ggf. verfeinern. ---
  {name:"T'rukan the Ascended",chapter:9,region:"Demeniss - Serpent Marsh (Süd)",quest:"Story Kap. 9 'The Sage of the Desert' / 'True Strength'",drop_weapon:"T'rukan's Fighting Spirit",drop_abyss_gear:"Abyss-Artefakt; Wooden Mask of Lost Justice",weakness:"–",parry_or_dodge:"Beides: Block + Counter (L1) bricht Guard, oder Combos dodgen",strategy:"Unbewaffneter Boss, 1 HP-Bar, sehr schnell und hart. Geduldig: im Block countern (Guard brechen) oder Combos ausweichen, dann 1-2 Hits, zurückziehen. Bei lila Glühen wegflüchten."},
  {name:"Goyen",chapter:9,region:"Abyss - Nest of Valor (via Spire of the Sun)",quest:"Story Kap. 9 'Unwavering Steps' (via Abyss)",drop_weapon:"–",drop_abyss_gear:"Witch's Ring; Greymane's Earring",weakness:"–",parry_or_dodge:"Turning Slash & Three-Slash-Combo parieren für Counter; Expertise-Move dodgen (Evasive/Aerial Roll)",strategy:"Spiegelt dein eigenes Moveset und trifft extrem hart (1-2-Hit-Kills). HP oben halten, großen Schild führen, Konter abwarten."},
  {name:"Thunder Tank",chapter:11,region:"Delesyia - Valvegard Garrison (SO)",quest:"Kap. 11 'Brave New World' / Fortress Keys. Garrison via Marni's Transporter (Force-Field)",drop_weapon:"Mechanical Clockwork Blaster",drop_abyss_gear:"Abyss-Artefakt x1",weakness:"Nicht block-/parrierbar; eigene Projektile reflektierbar",parry_or_dodge:"Dodge, kein Parry — Angriffe unblockbar. Distanz halten, Evasive Roll, Nature's Snare",strategy:"Abstand halten und mit Nature's Snare (Lv2, Nature's Retribution) die Raketen/Projektile abfangen und zurückwerfen; Spirit dazwischen aufladen."},
  {name:"The Crimson Nightmare",chapter:null,region:"Hernand - Fort Perwin",quest:"Optionale Faction-Quest. 3 Fort-Sektionen (Barracks/Infirmary/Artillery) befreien",drop_weapon:"–",drop_abyss_gear:"–",weakness:"Magie / Axiom Force (schwebender Würfel nur per Pull-Fähigkeit holbar)",parry_or_dodge:"AoE dodgen (Evasive Roll), kein Parry — Focused Repulsion/Axiom Force zum Runterziehen",strategy:"Erst die Banditen drumherum killen, Scarlet Blades Gas Mask gegen den Crimson-Smog-DoT tragen. In Focus Mode mit Focused Repulsion (R-Stick runter) den Würfel runterziehen, dann bursten."},
  {name:"Icewalker",chapter:null,region:"Hernand - Everfrost (N von Everfrost Cave)",quest:"Optionaler World-Boss (keine Quest). N von Everfrost Cave",drop_weapon:"–",drop_abyss_gear:"Power Core - Verse of Sowing (auch Haste I, Aegis I)",weakness:"–",parry_or_dodge:"Dodge/Evade — alle Angriffe unblockbar",strategy:"Zwei Icewalker teilen sich 1 HP-Bar; einen nach dem anderen fokussieren. Langsame Drehung: unblockbare Angriffe dodgen, hinter sie dashen für Backstabs + Stagger."},
  {name:"Grave Walker",chapter:null,region:"Hernand - Silent Falls Hideout (Hook Rapids)",quest:"Optionaler World-Boss (keine Quest). In der Höhle besiegen",drop_weapon:"Sorcerer's Staff (2H)",drop_abyss_gear:"Power Core - Verse of Sowing; Abyss Cell x1",weakness:"–",parry_or_dodge:"Dodge, kein Parry — Boulder-Wurf, Ground-Smash, Arm-Swing ausweichen, dann hinter ihn",strategy:"Optionaler Fels-Golem, sehr langsam. Telegrafierte Angriffe (Boulder-Wurf, Ground-Smash, Overhead-Slam) dodgen und hinter ihn dashen für mehrere Hits."},
  {name:"Ator, Archon of Antumbra",chapter:null,region:"Pailune - Cloister of Ruination (SW Silverwolf Mtn.)",quest:"Antumbra-Order-Faction-Questline 'Archon of Antumbra'",drop_weapon:"Darkbringer",drop_abyss_gear:"Seal of Pitch-Black Darkness; Abyss-Artefakt x1",weakness:"–",parry_or_dodge:"Dodge-Fokus — Rollen statt Blocken (volle Orb-Salve leert Stamina sofort)",strategy:"Defensiv: Angriff baiten, dodgen, countern. Nature's Retribution (Focus) wirft Orb-Projektile zurück (Stagger); Force-Palm-Combo baut die Stagger-Bar."},
  {name:"The Crimson Warden",chapter:null,region:"Demeniss - Demeniss Wildlife Park",quest:"Faction-Quest 'The Corrupted Greymane' (House Thorel), optional",drop_weapon:"–",drop_abyss_gear:"Abyss-Artefakt; Dark Red Goblet",weakness:"–",parry_or_dodge:"Schild hoch, Distanz schließen — sie ist hochbeweglicher Ranged-Bogen",strategy:"Schnelle Bogenschützin mit hoher Evasion, 1 HP-Bar. Nahkampf mit Schild: in die Ecke drängen, Force Palm stunnt/deaktiviert sie, dann 3-Hit-Combos für Stagger."},
  {name:"New Moon Reaper",chapter:null,region:"Demeniss - Southern Court",quest:"Optionaler Boss via Southern Court ('New Moon Reaper'-Quest)",drop_weapon:"Diverging Moon (2H Crescent-Spear)",drop_abyss_gear:"–",weakness:"Stagger-Bar füllt schneller als bei den anderen Lunar Reapers",parry_or_dodge:"Defensiv spielen; nach Block/Parry oder Dodge hinter den Boss countern",strategy:"Stärkster/ausgewogenster der drei Lunar Reapers — wartet auf Öffnungen. Erst Hof-Adds killen, dann nach Block/Dodge mit Max-Force-Palm-3-Hit-Combos die schnell füllende Stagger-Bar nutzen."},
  {name:"Half Moon Reaper",chapter:null,region:"Demeniss - Western Court (NW)",quest:"Optionaler Boss via 'Half Moon Reaper'-Quest, Western Court",drop_weapon:"Grasping Moon (2H Half-Moon-Spear)",drop_abyss_gear:"Abyss-Artefakt x1",weakness:"–",parry_or_dodge:"Scythe-Combos parieren für Counter; gegen unblockbare Crescent-Waves seitlich dodgen",strategy:"Aggressivster der drei Lunar Reapers — schnelle Scythe-Combos, Spins, trackende Crescent-Waves. Block/Parry für Counter, im Wave-Moment seitwärts, dann in der Erholung bursten."},
  {name:"Full Moon Reaper",chapter:null,region:"Demeniss - Eastern Court",quest:"Lunar-Judgment-Faction-Quest (House Elemore) — Eastern Court befreien",drop_weapon:"Circling Moon (Spear)",drop_abyss_gear:"–",weakness:"–",parry_or_dodge:"Mix: blockbare Schläge parieren (Moon Blade Slash, X-Strike); Blitz-Angriffe dodgen",strategy:"Hinter ihr bleiben (lange Speer-Reichweite, Crescent-Projektile); bewegt/dreht langsam — hinter ihr Backstabs für Stagger, dann finishen."},
  // --- Auto-recherchiert 2026-06-03 Welle 2 (game8/PowerPyx/GameRant/Fextralife-Item-Pages); Existenz je Boss verifiziert, Roster 42->69. Ohne Fextralife-Bild (Placeholder). KORREKTUR 2026-08-03: Karanda wurde damals faelschlich als Black-Desert-Verwechslung verworfen — sie ist ein echter Crimson-Desert-Boss (Pailune, Harpy Nest, Fraktionsquest 'Queen of the Skies'; belegt durch game8 596328 + GameRant + questlog-Asset abyssgear_karanda) und steht jetzt im Roster. NICHT erneut entfernen. ---
  {name:"Black Bear Captain",chapter:null,region:"Hernand - Deepfog Basin (N Calphade Farmhouse)",quest:"Miniboss beim Infiltrieren der Black-Bears-Basis (Kap. 6 'In Ashes' / 'Turning Tides')",drop_weapon:"–",drop_abyss_gear:"–",weakness:"–",parry_or_dodge:"Distanz halten & dodgen — Superarmor-Sprungangriff schließt Lücken; Ranged-Encounter, kein Parry-Duell",strategy:"Mit den Quest-Whistling-Arrows Artillerie rufen (one-shot + räumt die Soldaten); alternativ vom Turm aus schießen. Abstand halten (Superarmor-Gap-Closer unterbricht Schüsse). Droppt nichts."},
  {name:"Storm Crusher",chapter:11,region:"Delesyia - Aeronautical Research Base",quest:"Story Kap. 11 'Fortress Keys' (Brave New World) — Basis befreien, Fortress Key",drop_weapon:"Marni Musket (+ Delesyian Ornamental Shield)",drop_abyss_gear:"–",weakness:"–",parry_or_dodge:"Dodge — Charge-Angriffe aus Distanz ausweichen (sonst One-Shot); Kanonensalven auf rotes Aufblitzen",strategy:"Feuer-Tank, 1 HP-Bar, 3 distanzabhängige Angriffe (Ram nah, Explosivschüsse mittel, Raketen weit). Auf Distanz bleiben und Raketen mit Nature's Snare/Retribution zurückwerfen; oder Stun-Bar mit Turning Slash (R1+R2), mit Axiom Force + Aerial draufspringen und den grünen Kern R2-staben (kann buggen)."},
  {name:"Queen Spider",chapter:null,region:"Hernand - Arboria Castle (Nord)",quest:"Optional via Hernand-Faction ('Queen's Nest' / 'Queen of the Silkspun Citadel')",drop_weapon:"–",drop_abyss_gear:"Queen's Fangs (Core, Gift-Stab); Stirrups of the Open Sky; Abyss-Artefakt",weakness:"Feuer (brennt, fällt zu Boden)",parry_or_dodge:"Dodge/Deflect, kein Parry — Nature's Retribution gegen Gift-Projektile, Bite-Lunge ausweichen",strategy:"Mit Nature's Retribution Gift-Projektile zurückwerfen; Feuer priorisieren (brennt sie, fällt zu Boden = leichter Schaden). Mit Bogen beschießen während sie an der Wand klebt, harte Combos wenn sie runterspringt; explodierende Spinnen-Adds meist ignorierbar."},
  {name:"Cubewalker Lithus",chapter:null,region:"Hernand - Southern Quarry (Grace Estate)",quest:"Optionale Side-Quest 'A Rumor in the Southern Quarry' (House Felix)",drop_weapon:"Rune-Engraved Rock (2H)",drop_abyss_gear:"–",weakness:"Leuchtender Würfel am Kopf",parry_or_dodge:"Dodge — hinter Felsen Deckung gegen langsame, harte AoE-Steinwürfe; kein Parry",strategy:"Mit Axiom Force den leuchtenden Würfel aus dem Kopf ziehen → zerfällt in angreifbare Fragmente; Heavy-Attacks bis er sich neu zusammensetzt, wiederholen. Bogen empfohlen. Kein Element/Parry nötig."},
  {name:"Runewalker Vordis",chapter:null,region:"Hernand - Lake Kharonso (Scholastone)",quest:"World-Boss. 'Destroyed Barrier Stone of the Lake' — 4 Barrier-Stones am See wiederherstellen (nach 'Kharonso Troll Alliance')",drop_weapon:"Runewalker Shield (aus Vordis' Kopf craftbar)",drop_abyss_gear:"Abyss-Artefakt; Mossy Secret Map (alle Legendary-Fische)",weakness:"Leuchtendes Prisma am Kopf (kritischer Schwachpunkt)",parry_or_dodge:"Dodge & Deckung statt Block — Kharonso-Ruinen-Säulen nutzen",strategy:"Mit Axiom Force das leuchtende Prisma aus dem Kopf ziehen → Stein-Konstrukt kollabiert; im Fenster Heavy-Attacks spammen, bevor er sich neu formt. Säulen als Deckung. Kein Parry/Element dokumentiert."},
  {name:"Giath",chapter:null,region:"Hernand - Drakesfall Castle (Nord)",quest:"Optional. House-Celeste-Faction 'Bloodied Sword' — Giath & Wolf Trackers in Drakesfall Castle",drop_weapon:"Savage Sawblade (Unique 1H Sword)",drop_abyss_gear:"–",weakness:"Anfällig für Grapples (baut Stagger)",parry_or_dodge:"Dodge, kein zuverlässiges Parry — unblockbare Heavy-Power-Attacks mit langem Wind-up sofort ausweichen",strategy:"Wolf-Trackers-Anführer, großer Plattenträger mit Curved-1H-Sword und schnellen Multi-Hit-Combos: ganze Combo abwarten, dann countern. Lange-Wind-up-Power-Attacks dodgen (nicht blocken), zwischen Dodges grappeln für Stagger. Viel Heil-Food mitnehmen."},
  {name:"Sizlek the Insatiable",chapter:null,region:"Hernand - Ruined Chapel (SO, Steel Mountains)",quest:"Optional. Finale Faction-Questline der Hernandian Parish of Solumen ('Ruined Chapel'); 'Mysterious Arrow' @ Glenbright Farm",drop_weapon:"Lightningblade of Greed (auch: Greedy Lightningblade)",drop_abyss_gear:"Storm Fang (aus Goldbranch Plate Crown; Chain-Lightning)",weakness:"–",parry_or_dodge:"–",strategy:"Optionaler Fundamentalist-Goblin-Boss. Vorbereitet kommen (Kuku Pot, Focused Force Palm). Quellen nennen keine klare Parry/Dodge-Linie oder Element-Schwäche. Drop: Greedy Lightningblade + Goldbranch Plate Crown (→ Storm Fang Abyss Gear)."},
  {name:"Sir Catfish",chapter:null,region:"Hernand - Vellua/Vallua (Süd-Küste, Teich)",quest:"Optionaler Faction-Boss. Vellua Fishermen's Guild 'Beyond the Silent Waves'",drop_weapon:"–",drop_abyss_gear:"Abyss-Artefakt; Catfish Plate Helm (Feuer-Res); 'Voyages of Sir Catfish'",weakness:"–",parry_or_dodge:"Beides: an Land langsam → dodgen & Flanke treffen; schnelle Angriffe gut parier-/konterbar",strategy:"An Land locken (dort viel langsamer), durch Angriffe dodgen und die Flanke treffen (schnelle Hits auch parierbar). Wasserfontänen-Hazard meiden (Blasen im Teich). Heil-Food = Hauptheilung im langen Fight."},
  {name:"Hemon Beindel",chapter:null,region:"Hernand - Fort Hellwood (W Glenbright Manor)",quest:"Optional. Hellhound-Questline 'The Rabid Hound of Hellwood' (nach 'Reliquary of Saint Senia')",drop_weapon:"The Hound (2H Greatsword; AoE 'Hound's Claws')",drop_abyss_gear:"Abyss-Artefakt (+ Skillpunkt)",weakness:"–",parry_or_dodge:"Slash-Angriffe parieren (bricht Combo, Stagger); Spin-Angriffe dodgen (nicht blocken)",strategy:"Auf Hemon fokussieren, Bogenschützen ignorieren (er bleibt nah). Slash-Combos parieren für Konter, Multi-Hits nicht blocken (Stamina). Breite Spin-Angriffe seitlich ausweichen (bei niedriger HP schneller/größer)."},
  {name:"Gwen Kraber",chapter:null,region:"Hernand - Roothold (NO)",quest:"Frozen-Eldertree-Questline (House Celeste)",drop_weapon:"Frostfang (2H Speer, aus der Arena)",drop_abyss_gear:"Icewing Plate Armor mit Shattering Frost (Eis-Imbue)",weakness:"–",parry_or_dodge:"Dodge — schnelle Speer-Dashes/Thrusts vorwärts/seitlich ausweichen; Parry nicht ratsam",strategy:"Schnelle Speer-Kämpferin mit Long-Reach-Thrusts, Eis-Imbue und Klon-Beschwörung, aber niedrige HP. Dashes dodgen (nicht parieren), dann Heavy-Attacks — kann sie bis zum Tod stunlocken."},
  {name:"Forestwalker Tervis",chapter:null,region:"Pailune - Wayward Woods",quest:"World-Boss, wandernd in den Wayward Woods (keine Quest nötig)",drop_weapon:"–",drop_abyss_gear:"–",weakness:"Feuer (Holzkörper – feuer-verzauberte Waffen beschleunigen den Kill)",parry_or_dodge:"–",strategy:"Uralter Baumgolem (Ent): eine in einem Baum gefangene Seele, Körper aus verschlungenen Wurzeln und Stämmen. Langsam, aber wuchtige Schläge mit den riesigen Armen. Feuer-Waffen/Skills brennen den Holzkörper schneller nieder. (Parry/Dodge-Details unverifiziert.)"},
  {name:"Bloodwalker Crussis",chapter:null,region:"Pailune - Silver Wolf Mountain (Süd)",quest:"Pailune-Militia 'Bloodied Path' / 'Hunting Red' — Bounty in Pailune City",drop_weapon:"–",drop_abyss_gear:"Abyss-Artefakt; Quest: Bloodstained Blessing, Crossroads Necklace, 7 Silber",weakness:"–",parry_or_dodge:"Dodge statt Block (Hits können Guard brechen); mit Focused Repulsion/Explosiv-Pfeilen Stagger aufbauen",strategy:"Ancient-Walker-Koloss (wie Cubewalker Lithus) mit Schutz-/Invuln-Totem: in der Invuln-Phase 5 Totems zerstören, dann ist er angreifbar. Mit Focused Repulsion (oder Explosiv-Pfeilen) staggern für große Fenster; dodgen statt blocken."},
  {name:"White Bearclaw",chapter:null,region:"Pailune - Vat'nholl Fortress",quest:"Optional, 'Shadows of Beasts' (Pailune Militia) — Festung befreien",drop_weapon:"–",drop_abyss_gear:"Ashad Plate Helm",weakness:"–",parry_or_dodge:"Dodge",strategy:"Seine Angriffe gehen nach vorn — hinter ihn repositionieren und den Blind Spot treffen. Bei seinem Ice-Shard-Sprung Distanz halten und in den Lücken zwischen den Eissplittern stehen. Kein Parry/Element dokumentiert."},
  {name:"White Bear of the High Mountains",chapter:null,region:"Pailune - Fort Askelund",quest:"Optional, Pailune-Militia 'The Unending Threat of the Black Bears'",drop_weapon:"Split Tooth (2H Greataxe, 3 vorinstallierte Cores / 5 Slots)",drop_abyss_gear:"(im Split Tooth)",weakness:"–",parry_or_dodge:"Dodge — breite Spins nicht zuverlässig parierbar; seitlich (nicht rückwärts) ausweichen",strategy:"Distanz halten und erst nach Ende seiner Combo-Strings kontern (lange Reichweite, hoher Schaden). Telegrafierten Straight-Line-Charge und breite Spins seitlich ausweichen, dann 2-3 Hits in der Erholung."},
  {name:"Tarandus the Ashen",chapter:null,region:"Pailune - Odeck (Final; via Volvior/Verheim/Volstein Ruins)",quest:"Pailune-Faction-Questline (Name unverifiziert: 'Executioner of Justice' / Odeck-Tribe)",drop_weapon:"Ashen Execution (Greathammer)",drop_abyss_gear:"Abyss-Artefakt",weakness:"–",parry_or_dodge:"Nur Dodge — niemals Parry/Block; Greathammer bricht Guard und macht vollen Schaden",strategy:"Schneller, aggressiver Greathammer-Boss mit weiten Swings und tracking 'Jump Slams'. In Bewegung bleiben, außerhalb der Combo-Reichweite. Durch Angriffe dodgen (nie blocken/parieren), in den kurzen Erholungsfenstern 1-2 Hits."},
  {name:"Titan",chapter:null,region:"Pailune - Windsong Peaks (Scorched Mountain)",quest:"Optionaler Faction-Boss. Stjar-Clan 'Master of Thunder' + 'Ancient Barrier'",drop_weapon:"Reckoning (2H Speer)",drop_abyss_gear:"–",weakness:"Blitz (Angriffe machen Blitzschaden/Shock; Lightning-Res tragen)",parry_or_dodge:"Dodge — Angriffe unblockbar; Turning Slash i-frames nutzen",strategy:"Nicht parieren (unblockbar) — alles dodgen, Turning Slash (R1+R2) für i-frames gegen Blitz. Nur die freie Haut an der Hand nach Ground-Slam treffen (Panzerung = kein Schaden) bzw. den Nacken-Schwachpunkt, v.a. in der Gigantified-Phase. Starke Blitz-Resistenz + viel Heilung."},
  {name:"Moren the Mistwood Huntmaster",chapter:null,region:"Pailune - Wayward Woods (N Ridgehunter Tannery)",quest:"'The Sport Hunter' (Longleaf Tribe) — mit Laterne spuren",drop_weapon:"–",drop_abyss_gear:"–",weakness:"–",parry_or_dodge:"Dodge — durch Angriffe weben, Flanken treffen (kein Parry)",strategy:"Berittener Jäger auf Icicle-Edge-Alpine-Ibex mit Schwert + Tower-Shield, wechselt beritten/zu Fuß. Mit Turning Slash entreiten, dann durch Angriffe weben und Flanken treffen. Drop: Alpine Ibex Horn → Sigil of Solidarity (Ibex-Mount)."},
  {name:"Mountain God Boar",chapter:null,region:"Pailune - Odeck (nahe Silver Wolf Mountain)",quest:"World/Legendary-Boss. Nach Kap. 7 + Pailune freundlich; 'Lumberjacks' Witness Report'; ~15-20 Bäume fällen → spawnt am letzten Baum (+ ~4 kleine Eber)",drop_weapon:"–",drop_abyss_gear:"–",weakness:"Feuer",parry_or_dodge:"Dodge — Haupt-Bedrohung sind Vorwärts-Charges (Vorderbeine heben sich zuerst)",strategy:"Single-Phase: Eber chargt/slamt und ruft ~4 kleine Eber. Feuer-Skills (ideal Elemental Turning Slash mit Feuer) füllen schnell die Stagger-Bar → Finisher, wiederholen. Telegrafierten Charge (Vorderbeine) dodgen, auf flachem Boden kämpfen."},
  {name:"One-Eyed Jackal Captain",chapter:null,region:"Pailune - Skallcove (N City of Pailune)",quest:"Miniboss in 'Where Lightning Strikes' (Stjar Clan)",drop_weapon:"–",drop_abyss_gear:"–",weakness:"–",parry_or_dodge:"–",strategy:"Recht leichter Miniboss mit wenigen wiederholten Angriffen (game8 vergleicht ihn mit Antumbra's Sword, weniger Schaden). Alles auf den Captain fokussieren, die endlos spawnenden Mobs ignorieren. Droppt nichts."},
  {name:"The Forgotten General",chapter:null,region:"Pailune - The General's Tomb (NW Silverwolf Mtn., bei Odeck)",quest:"Endgame 'Overwhelming Being'. Pailune-Faction komplett + Odeck-Subquest 'Slumbering Soul'",drop_weapon:"Awakened Spirit (2H Halberd; 'Judgment of the Soul')",drop_abyss_gear:"Judgment of the Soul (blaues Phantom auf Counter Stance)",weakness:"Feuer (Fire-Imbue/Heavy-Impact nötig, sonst kaum Schaden)",parry_or_dodge:"Dodge-Fokus — mit Aerial Force Palm über die arenaweiten 'Odeck's Army'-Sweeps, dann Meteor Kick",strategy:"Hoch-HP, aggressives Overwhelming Being: spawnt mitten im Angriff eine Illusion (verdoppelt das Schadensfenster) — zweiten Swing respektieren. Arenaweite Illusions-Army-Sweeps mit Aerial Force Palm überspringen, mit Meteor Kick kontern. Fire-Imbue/Heavy-Impact mitbringen (sonst sehr resistent)."},
  {name:"Antumbra's Staff",chapter:null,region:"Pailune - Sanctum of Solace (O Wayward Woods)",quest:"Optional. 'The Witch of Kindness' (Bari) — Sanctum reinigen",drop_weapon:"Guidance of Dark Pursuit",drop_abyss_gear:"Abyss-Artefakt",weakness:"–",parry_or_dodge:"Mix: Melee-Combo (bis 3 Hits) parier-/blockbar; Schatten-Projektile dodgen; Teleport-Combo ausweichen",strategy:"Schatten-Magier: aggressiv und nah bleiben (begrenzt das Casten), den roten geladenen Ground-Slam mit Force Palm unterbrechen, in Focus Mode mit Nature's Retribution/Snare die Homing-Schatten-Projektile ablenken/absorbieren. Teleport-Volleys dodgen (nicht blocken); Infinite + Explosive Arrows können stagger-locken."},
  {name:"Skull Knight",chapter:null,region:"Demeniss - Spire of Frost (frozener Norden, O Beighen)",quest:"Optional 'The Frostwarden' — 7 Steinlaternen im Spire of Frost entzünden (Start in Beighen, Kap. 7)",drop_weapon:"Frozen Anguish (2H Greatsword, Truhe 1. Stock — kein Kill-Drop)",drop_abyss_gear:"Quest: Frostcursed Plate Boots + Passage-of-Malice-Puzzle; Frostcursed-Set/Frostward-Gears Gebiets-assoziiert",weakness:"–",parry_or_dodge:"Dodge — seitlich rollen und gegen seine Swing-Richtung umkreisen (nicht rückwärts); kein Parry",strategy:"Nicht direkt besiegbar — er flieht bei ~20-25% HP; man tötet ihn, indem man alle 7 Laternen im Spire of Frost entzündet (hebt den Fluch). Im Fight teleportiert er hinter dich für Heavy-Strikes + breite Greatsword-AoE: seitlich dodgen/umkreisen, in der Pause kontern. Hohe Eis-/Kälte-Resistenz mitbringen."},
  {name:"Stonewalker Antiquum",chapter:null,region:"Demeniss - Gate of Truth (Pillar of Light)",quest:"World/Optional via 'Gate of Truth' (Secrets of the Ancient Ruins / Tariv-Sorcerers); braucht wohl Constellation Helmet (Scholastone)",drop_weapon:"Earthsplitter (2H Greataxe, Oongka-exklusiv)",drop_abyss_gear:"Abyss-Artefakt; zufälliger Power Core (Kuku-Upgrades am Kilndren)",weakness:"Leuchtendes rotes Auge (einziger Schwachpunkt); Körper = Stein-Panzerung, immun gegen Slash/Pierce",parry_or_dodge:"Dodge — Laser-Beams ausrollen; Gimmick-Boss, kein Parry",strategy:"Laser dodgen, dann aufs rote Auge locken und mit Axiom Force (L3, L2 halten + rechten Stick zurück) das Auge herausziehen → Boss gestunnt und gespalten; R2/R1+R2 spammen solange am Boden. Phase 2: Kopf fliegt hoch → Axiom-Force-Augen-Pull wiederholen, dann finishen."},
  {name:"Tristan the Flame Knight",chapter:null,region:"Demeniss - Flame Knights Castle (West)",quest:"Optional. House-Azerian-Flame-Knight-Questline ('Letters of Ashes'/'Greed and Ashes') — Castle befreien",drop_weapon:"Spada Sword & Drake Shield (versteckt nahebei nach dem Fight)",drop_abyss_gear:"Abyss-Artefakt; Seal of Devotion; Scorchflame Plate Gloves; Multishot-Skill",weakness:"–",parry_or_dodge:"Feuer-AoEs dodgen; Superarmor-Moves (Phoenix Dive, Great Flame Explosion) nicht staggerbar → Distanz",strategy:"Alle Nahkampf-Hits machen Feuerschaden; zwei Superarmor-Feuer-Moves (Phoenix Dive, Great Flame Explosion, massive AoE) zwingend dodgen. Force Palm zwischen Combos für Stagger → Turning Slash (oft Focus für Spirit). In Arena-Säulen locken und mit Nature's Grasp an gebrochener Säule ~1/3 HP abziehen."},
  {name:"Mazzul, the Dark Justiciar",chapter:null,region:"Demeniss - Burnhand Quarry (Byron Estate)",quest:"Optional. House-Byron 'The Dark Justiciar' / 'One Step Ahead' (nach Demeniss-Befreiung Kap. 8 + Keglord)",drop_weapon:"Sanguine Knell",drop_abyss_gear:"Ashad Plate Gloves (Abyss-Slot); Abyss-Artefakt; Golden Beer",weakness:"–",parry_or_dodge:"Dodge — nicht blocken/traden (horizontaler Sweep zieht Stamina, staggert dich); Heavy-Swings & AoEs ausweichen",strategy:"2H-Axt-Nutzer mit starker Offense, schwacher Defense. Den langsamen Overhead-Cleave/Slam baiten für das sicherste Konter-Fenster; mobil bleiben (Ground-Slam, Aerial-Dive). Ranged-Builds (Focus/Keen Senses) über Melee empfohlen."},
  {name:"Keglord Garnier Mk. XXIII",chapter:null,region:"Demeniss - The Laughing Marionette",quest:"Optional. House-Marshell-Questline (Midnight Circus / 'Nightmare on Stage')",drop_weapon:"–",drop_abyss_gear:"Official Knight's Cloth Cloak; Tech Hat; 'Wrecked Keglord'-Material",weakness:"Grüne Schwachpunkte (Hände, Schultern, Kopf); zentrale Spule stun-anfällig; Lightning-Res hilfreich",parry_or_dodge:"Meist unvermeidbare Angriffe — eher durchheilen als dodgen; Raketen mit Nature's Retribution ablenken",strategy:"Zentrale Spule mit Turning Slash stunnen (gibt Schaden-Immunität), dann Stab auf die grünen Schwachpunkte — Hände/Schultern (Phase 1), Kopf (Phase 2). Da die meisten Angriffe nicht dodgebar sind: viel Heilung mitbringen (oder Raketensalven mit Nature's Retribution ablenken für großen Stagger)."},
  {name:"Queen Bismuth Oreback Crab",chapter:null,region:"Crimson Desert - Well of Enlightenment (S Forebearer's Barrens)",quest:"'Sage of the Desert'-Questline — nach 'The Oreback Crab in the Desert' / 'War Song of the Dusk'",drop_weapon:"–",drop_abyss_gear:"Abyss-Artefakt (+ 30x Bismuth Ore); befreit den Well of Enlightenment",weakness:"–",parry_or_dodge:"–",strategy:"Gimmick/Climb-Boss: per Triple-Jump + Glide auf den Panzer (oder Beine angreifen zum Immobilisieren), festhalten (L3), Kristallformationen zerstören → weiße Schwachadern freilegen, dann Heavy (R2) für je ~1/3 HP. Finalphase: zum Topf-/Schalen-Cluster auf dem Rücken laufen und mit Normal-Attacks zerschlagen = Instant-Kill."},
  // --- Auto-recherchiert 2026-06-03 Welle 3 (game8/PowerPyx/GameRant/TheGamer/Fextralife); Existenz je Boss verifiziert, Roster 69->97. Karanda-Verwerfung am 2026-08-03 revidiert (echter CD-Boss, siehe Roster-Eintrag oben); Kutum/Abyss Kutum als echte CD-Bosse bestaetigt. ---
  {name:"Dreadnought",chapter:null,region:"Delesyia - Marni's Laboratorium",quest:"'Forbidden Gatekeeper' / Fortress-Befreiung (Marni's Laboratorium, Fortress Key)",drop_weapon:"–",drop_abyss_gear:"Sonic Resonator (Pack/Rückenausrüstung, keine Waffe); Abyss-Artefakt; Frozen Heart Plate Cloak",weakness:"Sehr langsame Drehung (~2-3s für 180°) → Rücken offen für Backstabs; Stagger-Bar füllbar",parry_or_dodge:"Dodge — alle Angriffe unblockbar; Laser/Melee ausrollen (im Kreis um den Zyklopen-Laser)",strategy:"Dampf-Mech mit unblockbaren Heavy-Attacks (Drei-Arm-Swing, Charge, Ground-Slam, Zyklopen-Augenlaser, Laser-Regen). Im Kreis dodgen gegen den Laser, in der langsamen ~2-3s-Drehung hinter ihn dashen für Backstabs. Stagger-Bar mit Combos füllen → Stun → Finisher."},
  {name:"Cloud Fortress Orbian",chapter:11,region:"Delesyia",quest:"Story Kap. 11 'Truth and Reality' (Foreboding Shadow) — 'Flying Fortress Orbian'; braucht 'Whispers in the Wind'",drop_weapon:"–",drop_abyss_gear:"–",weakness:"Zentrales goldenes Auge/Core — invuln bis Stun-Bar voll, dann Shutdown (massiver Schaden); Bogen mit Charged/Focused Shot",parry_or_dodge:"Dodge — Ranged-Fight (Bogen); in Bewegung bleiben gegen Laser/Projektile",strategy:"Zwei Phasen: erst auf Blackstar (Drache) die äußeren gelben Cores mit Feuer zerstören, dann zu Fuß innen. Core-Boss: mit Bogen zielen, Charged/Focused Shot (Auge 4x markieren) für großen Schaden; oder Nature's Snare/Axiom Force für Sofort-Stun, dann im Shutdown bursten. Volle Pfeile, nicht sterben (sonst Festung von vorn)."},
  {name:"Marni's Machina Knight",chapter:null,region:"Delesyia - Marni's Outpost (NO Gorthak)",quest:"Faction 'Blade of Discipline' (auto bei Interaktion)",drop_weapon:"Electro-Mecha Longsword (2H, Lightning, 27 ATK; nicht upgradebar)",drop_abyss_gear:"Abyss-Artefakt",weakness:"Melee empfohlen; leicht pfeil-resistent; Stun-Bar für Fenster aufbauen",parry_or_dodge:"P1 (Longsword): 3-Hit-Combos parieren (L1), Opener-Overhead + Ranged-Slashes dodgen. P2 (Speer): alles dodgen, nicht parieren/blocken (Stamina)",strategy:"Zwei-Phasen-Teleport-Boss (mid-late game). Mobil bleiben gegen Teleports/Ranged, Lücke schließen, Turning Slash (R1+R2) + Forward Slash für die Stun-Bar, in Stagger-Fenstern bursten. P1: Parry/Turning Slash abwechseln; P2: voll auf Dodge (schnellerer Speer + Seeking-Cube/Lightning)."},
  {name:"Mechanicus",chapter:null,region:"Delesyia - Marni's Steel Armory",quest:"Faction 'Plating Debris' (Society of Progress)",drop_weapon:"Marni Tank Blaster (Hand Cannon)",drop_abyss_gear:"Machina Plate Armor Set",weakness:"–",parry_or_dodge:"Dodge — breite Frontal-Sweeps; nicht vorne stehen, seitlich ausweichen statt parieren",strategy:"Marni's Steel Armory via 'Plating Debris' befreien. Aus dem Frontbereich raus, breite Melee-Sweeps seitlich dodgen, von der Seite kontern. Drückt konstant, aber vorhersehbar (low Crit) — Stagger aufbauen, niederwerfen, dann Heavy-Schaden."},
  {name:"Ironwing REN-X",chapter:null,region:"Delesyia",quest:"Faction 'Wings Across the Sky' (nach Kap. 11, Blackstar-Mount nötig)",drop_weapon:"–",drop_abyss_gear:"–",weakness:"6 grüne Orbs an Flügeln/Rücken + 1 finaler im Zentral-Hatch; zuerst die Flügel-Geschütze zerstören",parry_or_dodge:"Dodge/Mobilität auf dem Drachen-Mount (kein Parry — Luftkampf, schnell zurück wenn abgeworfen)",strategy:"Mit dem Blackstar-Drachen hoch und auf die fliegende Maschine landen, sofort die Flügel-Auto-Turrets zerstören (sonst Abwurf). Mit Stab (R1+△) → Pierce (R2) die 6 grünen Orbs brechen, dann ins geöffnete Zentral-Hatch und den finalen Orb staben → Kill-Cutscene."},
  {name:"Clockwork White Horn",recur:"Mechanik-/Abyss-Variante des White Horn (Eternal Corridor, einphasig)",chapter:null,region:"Abyss - Clockwork Heart (Eternal Corridor)",quest:"Optionaler/geheimer Boss am Clockwork Heart (finale Arena des Eternal Corridor)",drop_weapon:"–",drop_abyss_gear:"–",weakness:"Feuer (Fire-Imbue brennt/staggert); Bonus-Schaden von Maschinen via Steelbane; macht Blitzschaden → Lightning-Res",parry_or_dodge:"Dodge/Roll (Parry unzuverlässig)",strategy:"Single-Phase, mechanische White-Horn-Variante. Seitlich rollen gegen Ground-Slams (Muster von 2-3) und Horn-Tackles, dann aus Flanke/Rücken kontern. Turning Slash (R1+R2) mit Fire-Imbue (L2+R2) für Stun + i-frames; Lightning-Res + Steelbane für Maschinen-Bonus."},
  {name:"Praevus the Ancient",chapter:null,region:"Crimson Desert - Abyss Debris (W Tashkalp)",quest:"Faction 'The Shackled God' (für Aeserion); einer der 3 Ancients",drop_weapon:"–",drop_abyss_gear:"Abyss-Artefakt; Memory of Ancient Nature; Ancient Earring; Ancient Wrath",weakness:"Per Bogen aus der Luft staggerbar; Hitze-Res-Rüstung essenziell (Feuerschaden)",parry_or_dodge:"Dodge — rollen löscht Feuer-Status und weicht Feuer-Lasern/Meteoren aus (kein Parry)",strategy:"Hoch-Level-Bogen (Lv3) mit Focused Shot baut Stagger während Praevus fliegt → zu Boden. Am Boden an die Nord-Felsen drängen und mit Melee/Heavy bursten. Ständig rollen (Feuer-Debuff löschen, Meteore meiden — Niederschlag beim Meteor = Instant-Kill)."},
  {name:"Primus the Ancient",chapter:null,region:"Delesyia - Daggerhead Monolith (N Serpent Shrine)",quest:"Faction 'Shackled God'; einer der 3 Ancients (Aeserion-Wächter)",drop_weapon:"–",drop_abyss_gear:"Ancient Reckoning (Wind-Core); Ancient Ring; Sage's Eye",weakness:"Bogen (Focused Shot) während Flug; Stun-Bar → zu Boden",parry_or_dodge:"Block — Homing-Missiles kaum dodgebar, mit Schild blocken statt parieren",strategy:"Flieger-Boss: mit Bogen zielen, Focused Shot (R1 markieren, Schnellpfeile) baut die Stun-Bar → Boden. Am Boden Melee-Finisher + Turning-Slash-Combos, beim Auffliegen Homing-Missiles mit Schild blocken, wiederholen."},
  {name:"Mudwalker Lutemir",chapter:null,region:"Pailune - Swamp of Despair",quest:"Optional, Longleaf-Tribe ('Concern of the Tannery' / 'Forest Drowned in Mud')",drop_weapon:"–",drop_abyss_gear:"Abyss-Artefakt; Rainstorm Necklace (Quest)",weakness:"–",parry_or_dodge:"–",strategy:"Optionaler Boss im Swamp of Despair. Lore: ein Ancient ohne Körper, Seele im Schlamm gebunden — formloses Monster, das Wasser/Erde des Waldes assimiliert. Detaillierte Kampftaktiken in verlässlichen Quellen nicht dokumentiert."},
  {name:"Bradie Gu",chapter:null,region:"Pailune/Demeniss - Bloodsteel Camp (Region umstritten)",quest:"House-Wells 'The Divine Echoes' / 'Deathchime'",drop_weapon:"–",drop_abyss_gear:"–",weakness:"–",parry_or_dodge:"Parry / Perfect-Dodge — nicht blocken (Stamina)",strategy:"Outlaw-Warlord mit schnellen Dual-Blade-Combos und Grapple-Countern. Heavy-Attacks meiden (er countert mit Grab); nicht blocken — Parry-Timing und Perfect-Dodges lernen, dann nach der Dual-Blade-Flurry in der Erholung kontern."},
  {name:"The Raging Tempest",chapter:null,region:"Demeniss - Silvermoon Tradehouse (Demeniss Port)",quest:"Silvermoon-Trade-Group 'The Day the Moonlight Waned' (nach Kap. 8)",drop_weapon:"–",drop_abyss_gear:"Abyss-Artefakt",weakness:"–",parry_or_dodge:"–",strategy:"Optionaler Faction-Boss der Silvermoon-Trade-Group-Questline am Silvermoon Tradehouse. Viel Instant-Heil-Food mitbringen. Detaillierte Weakness/Parry-Daten in den Quellen nicht belegt."},
  {name:"Kutum",recur:"Overworld-Version — existiert auch als stärkeres Abyss Kutum",chapter:null,region:"Demeniss - Kingshield Dig Site (Marshell Estate)",quest:"Faction 'Beneath the Dig Site' (optional)",drop_weapon:"Kutum Shield",drop_abyss_gear:"Abyss-Artefakt / Power Core (via Axiom Force)",weakness:"Leuchtendes rotes Auge oben (Abyss-Kreatur in Steinpanzerung — nur das Auge verwundbar)",parry_or_dodge:"Dodge",strategy:"Wenn Kutum abtaucht, weg vom aufgewühlten Boden rollen (taucht sonst unter dir auf). Beim Auftauchen Axiom Force (L3) aufs rote Auge, L2 halten + rechten Stick ziehen → Auge herausreißen, Stun. Im langen Fenster R2-Schaden, bei wenig Stamina Turning Slash (R1+R2)."},
  {name:"Antumbra's Spear",chapter:null,region:"Demeniss - Sanctum of Revelation (NO Serpent Marsh)",quest:"Witches-Faction (Witch of Strength / Cloister of Ruination), optional",drop_weapon:"Thorn of Dark Pursuit (2H Speer)",drop_abyss_gear:"Abyss-Artefakt",weakness:"Kein Element; sehr anfällig für Force Palm (stunnt mehrere Sekunden)",parry_or_dodge:"Mix: physische Speer-Thrusts parieren; Magie-Projektile + Teleport-Shadow-Pierce + Phalanx-Klone dodgen/gliden",strategy:"Seitlich bleiben (lange Speer-Reichweite), mit Force Palm wiederholt stunnen, dann Heavy/Pfeile/Turning Slash. Physische Thrusts parieren, Magie/Teleport-Dashes dodgen/gliden; Säulen (Axiom Force) und Aerial-Glide gegen die Dash-Combos."},
  {name:"Queen Stoneback Crab",chapter:null,region:"Delesyia - Stoneback Crab Wetlands",quest:"Side-Quest 'The Queen's Lake' (Diederik; ab Kap. 3)",drop_weapon:"–",drop_abyss_gear:"Abyss-Artefakt (+ 2x Diamant, 3x Granat, 5x Azurit)",weakness:"3 grüne Schwachpunkte am Panzer; danach der magische Krug/Topfstapel oben = Kill-Punkt; Körper sonst invuln",parry_or_dodge:"Dodge (rückwärts dashen vor Ground-Slams, Boulder meiden) — kein Parry/Melee-Duell",strategy:"Mit Force Palm die Erze vom Rücken schlagen, dann auf den Boss klettern und die 3 grünen Schwachpunkte staben (blaue HP-Bar). Boulder-Würfe/Ground-Slams dodgen. Wenn die rote Bar erscheint, den freigelegten magischen Krug/Topfstapel oben mit Normal-Attacks finishen."},
  {name:"Aeserion, the Great Serpent",chapter:null,region:"Delesyia - Serpent Shrine (S Dewhaven)",quest:"Faction 'Shackled God' — erst die 3 Ancients (Priscus/Primus/Praevus) + Kap.-9-Force-Palm-Upgrade",drop_weapon:"Aeserion Sword (1H); schaltet 10 craftbare Aeserion-Waffen frei (Blueprint)",drop_abyss_gear:"–",weakness:"Freigelegte goldene Korruptions-Cores nach Zerstören der Bismuth-Emitter; Lightning-Res (periodische Blitze)",parry_or_dodge:"Kein klassischer Parry/Dodge-Fight — auf dem Rücken reiten, beim Emitter-Entladen vom elektrifizierten Rücken weg",strategy:"Auf Aeserions Rücken klettern, die 3 Bismuth-Emitter mit Turning Slash (R1+R2) brechen, dann Focus (R3) auf den goldenen Schwachpunkt → loslassen zerstört den Core. Schnell arbeiten (Emitter graben sich neu ein), bei Elektrifizierung weggehen. Endgame-Tier — Heilung mitbringen."},
  {name:"Balthazar, the Wyvernflame",chapter:null,region:"Delesyia - Fort Windridge (SO Three Brothers' Cliff)",quest:"Faction 'The Wyvernflames' (Ironwheel of Dewhaven; ab Kap. 5+)",drop_weapon:"Wyvern Blaster (Hand Cannon, Oongka)",drop_abyss_gear:"Abyss-Artefakt",weakness:"Ranged; 0 Defense (voller Rohschaden); Cannon-Fire mit Nature's Snare absorbier-/umlenkbar",parry_or_dodge:"Dodge/Block (kein Parry)",strategy:"Balthazar kämpft v.a. auf Distanz mit Cannon-Fire. Mit Focus die Zeit verlangsamen und Sprung-Angriffe meiden, mit Nature's Snare Schüsse absorbieren/zurückwerfen + eigene Ranged-Salven, dann mit Melee finishen wenn die HP fällt."},
  {name:"Ogre",chapter:null,region:"Crimson Desert - Desolate Megalith Altar (bei Tashkalp)",quest:"Optionaler/geheimer Boss (keine Story-Quest)",drop_weapon:"–",drop_abyss_gear:"Ogre's Necklace; Ogre's Ring; Colossal Might",weakness:"–",parry_or_dodge:"Dodge",strategy:"Nah bleiben und diagonal vorwärts dodgen gegen den Kegel-AoE seiner Doppel-Hand-Slam-Combos. Höchstens 3 Hits nach Combo-Ende, dann reposition. Beim Vier-Slam-Sprung auf den Boss zulaufen wenn der Boden dunkelt, dann beim Aufschlag dodgen. Back Hang vermeiden."},
  {name:"Crookrock Walker",chapter:null,region:"Crimson Desert - Forebearer's Barrens",quest:"Optionaler Boss (keine Quest)",drop_weapon:"–",drop_abyss_gear:"Abyss Cell; Power Core - Spire of Defiance; Composure I; Destruction I",weakness:"Flanken/Seiten offen",parry_or_dodge:"Dodge / auf die Flanke reposition (langsame Wind-ups; kein Parry)",strategy:"Langsamer Stein-Golem auf einem Abyss-Nexus. Auf der Flanke bleiben (telegrafierte langsame Angriffe meiden), frei Combos setzen. Nach Stagger zerfällt er in Steinstücke — eines der Fragmente angreifen zum Finishen."},
  {name:"Desert Marauder Rusten",chapter:null,region:"Crimson Desert - Forebearer's Barrens (N Tashkalp)",quest:"'Marauder of the Desert'",drop_weapon:"–",drop_abyss_gear:"–",weakness:"Räder — nicht per Normal-Angriff; nur eigenes umgelenktes Cannon-Fire trifft die Räder, dann den Core",parry_or_dodge:"Weder — Nature's Snare Retribution fängt/lenkt Cannon-Fire um (mobil bleiben gegen Tracking-Shots)",strategy:"Cannon-Marauder, immun gegen Direktangriffe. Mit Nature's Snare Retribution die Tracking-Projektile sammeln und auf die Räder umlenken (2 Räder einer Seite). Wenn er hält und die Front-Hatch öffnet: rein und den Core staben."},
  {name:"Muskan",chapter:null,region:"Crimson Desert - The Bonepit (City of Tommaso)",quest:"'Emperor of the Bonepit' (erst Drakane & Jaleel besiegen)",drop_weapon:"Combat God's Plate Gloves (Unarmed, Blitzschaden)",drop_abyss_gear:"Relentless",weakness:"Kein Element; meiste Angriffe Superarmor; verwundbar nach Parry der Knie+Punch-Combo bzw. Dodge der Charges; Grapple/Spirit senken HP gut",parry_or_dodge:"Meist Dodge — Knie-Punch-Combo parierbar, meiste Angriffe Superarmor; Säulen für Line-of-Sight; Charge/Heavy-Punch blockbar",strategy:"Unarmed-Gloves anziehen (z.B. Ordinary Gloves), erst Spirit/Health/Unarmed/Grappling upgraden. Geduldig nach seinen Angriffen kontern, mit Grappling + Spirit-Moves chippen. Bei dunklem Screen (invuln Champion's Combo) weiter dodgen und hinter einer Säule verstecken. Drop: die BIS-Unarmed-Gloves."},
  {name:"Gristle, the Sandfang Marauder",chapter:null,region:"Crimson Desert - Howlsands Camp",quest:"'Outlaws of the Desert'",drop_weapon:"Tommasoan Bow",drop_abyss_gear:"Abyss-Artefakt",weakness:"–",parry_or_dodge:"Parry",strategy:"Optionaler Banditen-Anführer am Howlsands Camp; als Humanoid parry-anfällig (erfolgreicher Parry staggert ihn für Free-Damage). Detaillierte Mechanik nicht belegt."},
  {name:"Skevald the Carrion King",chapter:null,region:"Crimson Desert - Hyena Den (SO Tashkalp Town)",quest:"Bounty 'Skevald, the Carrion King' (Lords of Unclaimed Lands)",drop_weapon:"–",drop_abyss_gear:"Putrid Touch (Gift-DoT-Abyss-Gear) + Abyss-Artefakt",weakness:"Feuer (entflammt → windet sich am Boden)",parry_or_dodge:"Dodge",strategy:"Hyänen-Rudel per Laternen-Spur tracken, erst die Hyänen mit Pfeilen ausdünnen (sonst Sammel-Aggro). Seitlich gegen seine schnellen Charges, Bite-Combo abwarten, dann kontern. Er stößt beim Treffer Gift aus — Food mitbringen, mobil bleiben. 2 Phasen (verschwindet, neu tracken); Feuer staggert."},
  {name:"Ravok of the Savage Fangs",chapter:null,region:"Crimson Desert - Tashkalp",quest:"'Savage Fang' / 'Master of the Wetlands'",drop_weapon:"Volcanic Blaster",drop_abyss_gear:"Abyss-Artefakt",weakness:"–",parry_or_dodge:"Charges seitlich dodgen; nach Combo-Ende parry-countern; nicht blocken",strategy:"Optionaler Roaming-World-Boss (kann beim Erkunden ambushen). Aggressive Charges seitlich umgehen, am Combo-Ende mit Parry-Countern die Öffnungen nutzen. Heavy-Rüstung + Food für den langen Fight."},
  {name:"Merrick, the Knight of Fortune",chapter:null,region:"Crimson Desert - Crimson Mountains Fortress",quest:"Faction 'The Crimson Desert's Knight of Fortune' (Lords of Unclaimed Lands)",drop_weapon:"Sword of Greed",drop_abyss_gear:"Hologram Projector",weakness:"–",parry_or_dodge:"Dodge (schwerer 2H-Warhammer, langsame Crushing-Swings)",strategy:"Optionaler Faction-World-Boss in goldener Rüstung, hält die Crimson Mountains Fortress; früher schon getroffen, hier härterer Rematch (~2.227 HP, 120 Def). Schwingt aggressiv einen 2H-Warhammer — Distanz schaffen und die Erholung nach den Platten-Slams bestrafen. Detaillierte Strategie nicht breit belegt."},
  {name:"Samara the Sandwatcher",chapter:null,region:"Crimson Desert - Izvatu Fortress (Golden Plains)",quest:"'Bullets Piercing the Sandstorm' (The Dusksongs — Izvatu Fortress befreien)",drop_weapon:"Gustav Musket",drop_abyss_gear:"–",weakness:"Kein Element; verwundbar in der Lande-Erholung nach der Wall-Barrage; Projektile mit Nature's Snare reflektierbar",parry_or_dodge:"Dodge (zu ihr rollen wenn ihre Gun funkt; kein Parry)",strategy:"Ranged-Firearm-Boss, wechselt zwischen Wall-Salven von oben und Bodenebene. Die kurze Lande-Animation mit voller Combo bestrafen, bei erhöhten Explosiv-Salven Deckung (Tore) nutzen. Nature's Snare blockt/reflektiert ihre Schüsse für Heavy-Schaden."},
  {name:"The Masked Liberator",chapter:null,region:"Crimson Desert - Fort Manub (Tashkalp)",quest:"'The Master of Masks' (The Faceless / Lords of Unclaimed Lands)",drop_weapon:"Shadow of the Past Pistol; Oblivion of the Past (Greathammer, Oongka)",drop_abyss_gear:"The Masked Liberator's Cloth Armor (6-teilig, Kliff)",weakness:"–",parry_or_dodge:"Dodge (schnelle Dual-Dagger, Smoke-Teleports, Wurfbomben; kein belegtes Parry-Fenster)",strategy:"Erst die Faceless-Gegner clearen und die 3 Truhen in Fort Manub öffnen, vorher heilen/repositionieren. Sie teleportiert per Smoke-Bombs, wirft Bomben und nutzt akrobatische Dagger-Combos — in Bewegung bleiben, nach dem Wiederauftauchen bestrafen, Würfe dodgen statt tanken."},
  {name:"Abyss Kutum",recur:"Abyss-Variante des Kutum (stärker: Stagger- und Fernkampf-Phasen)",chapter:null,region:"Abyss - Twisted Thicketway (via Sage's Peak)",quest:"Optionale Abyss-Puzzle-Kette (Twisted Thicketway / Spire of the Stars, Kap. IV)",drop_weapon:"–",drop_abyss_gear:"Abyss-Artefakt; Power Core (Spire of Defiance)",weakness:"Abyss-Core (roter Diamant) — mit Axiom Force ziehen; freigelegtes Auge per Bogen staggerbar",parry_or_dodge:"Dodge (kein Parry): vor der Laser-Barrage sprinten, nach dem Burrow seitlich timen beim Ground-Slam",strategy:"Mit dem Bogen die Stagger-Bar aufbauen, das Auge runterholen, dann Axiom Force den roten Abyss-Core herausreißen für ein großes Fenster — dabei Laser-Regen und Burrow-Slam dodgen. Schneller Cheese: außerhalb der Arena einen Baum schlagen und mit Nature's Grasp draufhauen (One-Shot)."},
  {name:"Black Bear Siege Engine",chapter:6,region:"Pailune - Calphade Territory",quest:"Story Kap. 6 'Hidden Fangs'",drop_weapon:"–",drop_abyss_gear:"–",weakness:"Whistling Arrows (Luftbombardement zerstört die Panzerung); Stahlpanzerung sonst resistent",parry_or_dodge:"Weder — Ranged-Objective: zu Pferd ranreiten, Whistling Arrow schießen, weiterreiten",strategy:"Radial-Menü (D-Pad rechts) → Whistling Arrows wählen und jedes gepanzerte Belagerungsgerät mit Kliffs Bogen beschießen → Luftbombardement zerstört es. Alle 5 Tanks in den süd-/zentralen Feldern; Whistling Arrows an freundlichen Lagern nachfüllen (ein Light/Heavy-Skill bricht sie auch direkt)."}
];
